/**
 * Unit tests for DOMNodePointer.getLocalName
 */
public class DOMNodePointer_getLocalName_TriageGen1Test {

    @Test
    public void testGetLocalName_withNonNullLocalName() {
        // Case 1: localName is not null (covers the first if block)
        Node mockNode = mock(Node.class);
        when(mockNode.getLocalName()).thenReturn("myLocalName");

        String result = DOMNodePointer.getLocalName(mockNode);

        assertEquals("myLocalName", result);
    }

    @Test
    public void testGetLocalName_withNullLocalNameAndNoColon() {
        // Case 2: localName is null, getNodeName does not contain ':' (covers index < 0)
        Node mockNode = mock(Node.class);
        when(mockNode.getLocalName()).thenReturn(null);
        when(mockNode.getNodeName()).thenReturn("simpleName");

        String result = DOMNodePointer.getLocalName(mockNode);

        assertEquals("simpleName", result);
    }

    @Test
    public void testGetLocalName_withNullLocalNameAndWithColon() {
        // Case 3: localName is null, getNodeName contains ':' (covers index >= 0)
        Node mockNode = mock(Node.class);
        when(mockNode.getLocalName()).thenReturn(null);
        when(mockNode.getNodeName()).thenReturn("prefix:actualLocalName");

        String result = DOMNodePointer.getLocalName(mockNode);

        assertEquals("actualLocalName", result);
    }

    @Test
    public void testGetLocalName_withNullLocalNameAndTrailingColon() {
        // Case 4: localName is null, getNodeName ends with ':'
        Node mockNode = mock(Node.class);
        when(mockNode.getLocalName()).thenReturn(null);
        when(mockNode.getNodeName()).thenReturn("prefix:");

        String result = DOMNodePointer.getLocalName(mockNode);

        assertEquals("", result);
    }

    @Test
    public void testGetLocalName_withNullLocalNameAndLeadingColon() {
        // Case 5: localName is null, getNodeName starts with ':'
        Node mockNode = mock(Node.class);
        when(mockNode.getLocalName()).thenReturn(null);
        when(mockNode.getNodeName()).thenReturn(":onlyPrefix");

        String result = DOMNodePointer.getLocalName(mockNode);

        assertEquals("onlyPrefix", result);
    }
}
